import type { TvlChartContext, TvlExtension } from './hook';
export type AlertKind = 'price' | 'line' | 'study';
export type AlertOp = 'cross' | 'above' | 'below';
export type AlertStatus = 'active' | 'triggered' | 'cancelled';
export interface Alert {
    id: string;
    owner: string;
    sym: string;
    /** "Last" or "<column>@<resolution>" */
    source: string;
    kind: AlertKind;
    op: AlertOp;
    level: number | null;
    t0: number | null;
    p0: number | null;
    t1: number | null;
    p1: number | null;
    drawingId: string | null;
    message: string;
    status: AlertStatus;
    createdMs: number;
    triggeredMs: number | null;
    triggerValue: number | null;
}
export interface AlertInput {
    id?: string;
    sym: string;
    source?: string;
    kind: AlertKind;
    op?: AlertOp;
    level?: number | null;
    line?: {
        t0: number;
        p0: number;
        t1: number;
        p1: number;
    } | null;
    drawingId?: string | null;
    message?: string;
}
export interface AlertStore {
    readonly owner: string;
    /** the owner's alerts (active and triggered; not cancelled), newest first */
    list(): Alert[];
    /** active alerts on a symbol */
    active(sym: string): Alert[];
    subscribe(listener: () => void): () => void;
    /** create, or replace (same id), an active alert */
    put(input: AlertInput): Promise<string>;
    cancel(id: string): Promise<void>;
    close(): void;
}
/** "ES crosses 100.25", "ES crosses up the trend line", "NQ RSI 14 (1m) crosses down 70" */
export declare function describeAlert(a: Pick<Alert, 'sym' | 'source' | 'kind' | 'op' | 'level'>, fmt?: (v: number) => string): string;
export declare function providePageAlertStore(store: AlertStore): () => void;
export declare function onPageAlertStore(cb: (s: AlertStore | undefined) => void): () => void;
export declare function currentAlertStore(): AlertStore | undefined;
export declare const ALERT_COLOR = "#ff9800";
/** Active price alerts on `sym` as dashed lines on `series` (alerts tied to a drawing show on it instead). */
export declare function bindAlertLines(series: ISeriesApi<SeriesType>, store: AlertStore, sym: string): () => void;
